import{_ as s,I as n,o as d,c as l,b6 as t,J as i}from"./chunks/framework.BUXTSoD9.js";const p=JSON.parse('{"title":"Datenvisualisierung und Dashboards","description":"","frontmatter":{},"headers":[],"relativePath":"de-de/appendix/5-data/data-visualization.md","filePath":"de-de/appendix/5-data/data-visualization.md"}'),h={name:"de-de/appendix/5-data/data-visualization.md"};function o(g,e,u,c,m,b){const r=n("ChartTypeSelectorDemo"),a=n("DashboardLayoutDemo");return d(),l("div",null,[e[0]||(e[0]=t('<h1 id="datenvisualisierung-und-dashboards" tabindex="-1">Datenvisualisierung und Dashboards <a class="header-anchor" href="#datenvisualisierung-und-dashboards" aria-label="Permalink to “Datenvisualisierung und Dashboards”">​</a></h1><div class="tip custom-block"><p class="custom-block-title">Vorwort</p><p><strong>Ein gutes Diagramm sagt mehr als tausend Datenzeilen.</strong> Datenvisualisierung verwandelt abstrakte Zahlen in intuitive visuelle Darstellungen, die es ermöglichen, die Geschichte hinter den Daten in wenigen Sekunden zu verstehen. Von Excel-Diagrammen bis hin zu Grafana-Überwachungs-Dashboards — Visualisierung ist allgegenwärtig.</p></div><p><strong>Was wirst du in diesem Artikel lernen?</strong></p><p>Nach Abschluss dieses Kapitels wirst du Folgendes können:</p><ul><li><strong>Diagrammauswahl</strong>: Den geeignetsten Diagrammtyp basierend auf dem Zweck der Daten wählen</li><li><strong>Visualisierungsprinzipien</strong>: Die Kernprinzipien des Visualisierungsdesigns beherrschen</li><li><strong>Dashboard-Design</strong>: Verschiedene Layoutmuster für unterschiedliche Dashboard-Typen verstehen</li><li><strong>Tool-Ökosystem</strong>: Die Positionierung und Auswahl gängiger Visualisierungstools kennenlernen</li><li><strong>Häufige Fallen</strong>: Irreführende Diagramme und typische Visualisierungsfehler vermeiden</li></ul><table tabindex="0"><thead><tr><th>Kapitel</th><th>Inhalt</th><th>Kernkonzepte</th></tr></thead><tbody><tr><td><strong>Kapitel 1</strong></td><td>Diagrammtypauswahl</td><td>Vergleich, Trend, Anteil, Verteilung, Beziehung</td></tr><tr><td><strong>Kapitel 2</strong></td><td>Visualisierungsdesignprinzipien</td><td>Data-Ink-Ratio, Konsistenz, Lesbarkeit</td></tr><tr><td><strong>Kapitel 3</strong></td><td>Dashboard-Layout</td><td>Übersichtstyp, Vergleichstyp, Drilldown-Typ, Echtzeit-Typ</td></tr><tr><td><strong>Kapitel 4</strong></td><td>Tool-Auswahl</td><td>ECharts, D3, Grafana, Metabase</td></tr><tr><td><strong>Kapitel 5</strong></td><td>Häufige Fallen</td><td>Abgeschnittene Achsen, 3D-Kreisdiagramme, Farbführen</td></tr></tbody></table><hr><h2 id="_0-uberblick-warum-ist-visualisierung-notwendig" tabindex="-1">0. Überblick: Warum ist Visualisierung notwendig? <a class="header-anchor" href="#_0-uberblick-warum-ist-visualisierung-notwendig" aria-label="Permalink to “0. Überblick: Warum ist Visualisierung notwendig?”">​</a></h2><p>Das menschliche Gehirn verarbeitet visuelle Informationen viel schneller als Text. Ein Liniendiagramm lässt dich sofort erkennen, dass „die Verkäufe im letzten Monat zurückgegangen sind&quot;, während du bei derselben Information in Tabellenform Zeile für Zeile vergleichen müsstest, um zu demselben Schluss zu kommen.</p><p>Der Kernwert der Visualisierung:</p><ul><li><strong>Muster erkennen</strong>: Trends, Zyklen und Ausreißer sind in Diagrammen auf einen Blick erkennbar</li><li><strong>Entscheidungsfindung unterstützen</strong>: Auch Nicht-Techniker können Daten verstehen und an Entscheidungen teilnehmen</li><li><strong>Kommunikationseffizienz</strong>: Ein Bild sagt mehr als tausend Worte und reduziert Mehrdeutigkeiten bei der Dateninterpretation</li></ul><div class="tip custom-block"><p class="custom-block-title">Visualisierung ≠ schön aussehen</p><p>Das Ziel der Visualisierung ist es, <strong>Informationen zu vermitteln</strong>, nicht zu beeindrucken. Ein schlichtes, aber genaues Balkendiagramm ist weitaus wertvoller als ein auffälliges, aber schwer verständliches 3D-Diagramm.</p></div><hr><h2 id="_1-diagrammtypauswahl-das-richtige-diagramm-fur-die-richtige-geschichte" tabindex="-1">1. Diagrammtypauswahl: Das richtige Diagramm für die richtige Geschichte <a class="header-anchor" href="#_1-diagrammtypauswahl-das-richtige-diagramm-fur-die-richtige-geschichte" aria-label="Permalink to “1. Diagrammtypauswahl: Das richtige Diagramm für die richtige Geschichte”">​</a></h2><p>Der erste Schritt bei der Diagrammauswahl ist nicht „Welches Diagramm mag ich?&quot;, sondern „Welche Information möchte ich vermitteln?&quot;. Unterschiedliche Datenzwecke erfordern unterschiedliche optimale Diagrammtypen.</p>',15)),i(r),e[1]||(e[1]=t('<h3 id="schnellreferenz-zur-diagrammauswahl" tabindex="-1">Schnellreferenz zur Diagrammauswahl <a class="header-anchor" href="#schnellreferenz-zur-diagrammauswahl" aria-label="Permalink to “Schnellreferenz zur Diagrammauswahl”">​</a></h3><table tabindex="0"><thead><tr><th>Datenzweck</th><th>Empfohlenes Diagramm</th><th>Nicht empfohlen</th><th>Grund</th></tr></thead><tbody><tr><td>Größen vergleichen</td><td>Balkendiagramm, Balkendiagramm (horizontal)</td><td>Kreisdiagramm</td><td>Das menschliche Auge ist empfindlicher für Längenunterschiede als für Winkelunterschiede</td></tr><tr><td>Trends anzeigen</td><td>Liniendiagramm, Flächendiagramm</td><td>Balkendiagramm</td><td>Die Kontinuität der Linie suggeriert zeitliche Kontinuität</td></tr><tr><td>Anteile anzeigen</td><td>Kreisdiagramm (≤5 Kategorien), gestapeltes Balkendiagramm</td><td>3D-Kreisdiagramm</td><td>3D-Perspektive verzerrt die Flächenverhältnisse</td></tr><tr><td>Verteilung anzeigen</td><td>Histogramm, Boxplot</td><td>Liniendiagramm</td><td>Verteilung erfordert die Betrachtung von Häufigkeiten, nicht Trends</td></tr><tr><td>Beziehungen anzeigen</td><td>Streudiagramm, Blasendiagramm</td><td>Balkendiagramm</td><td>Die Beziehung zwischen zwei kontinuierlichen Variablen erfordert einen zweidimensionalen Raum</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Eine einfache Entscheidungsregel</p><ul><li><strong>Eine Variable</strong> → Histogramm (Verteilung) oder Zahlenkarte (KPI)</li><li><strong>Zwei Variablen</strong> → Liniendiagramm (Zeit vs. Wert) oder Streudiagramm (Wert vs. Wert)</li><li><strong>Mehrere Kategorien</strong> → Balkendiagramm (Vergleich) oder Kreisdiagramm (Anteil, ≤5 Kategorien)</li><li><strong>Mehrere Dimensionen</strong> → Radar-Diagramm oder Parallelkoordinaten-Diagramm</li></ul></div><hr><h2 id="_2-visualisierungsdesignprinzipien-die-daten-fur-sich-sprechen-lassen" tabindex="-1">2. Visualisierungsdesignprinzipien: Die Daten für sich sprechen lassen <a class="header-anchor" href="#_2-visualisierungsdesignprinzipien-die-daten-fur-sich-sprechen-lassen" aria-label="Permalink to “2. Visualisierungsdesignprinzipien: Die Daten für sich sprechen lassen”">​</a></h2><p>Eine gute Visualisierung ist nicht „hübsch&quot;, sondern „verständlich&quot;. Die mehreren klassischen Prinzipien, die Edward Tufte in „The Visual Display of Quantitative Information&quot; vorgestellt hat, sind bis heute eine wichtige Referenz für das Visualisierungsdesign.</p><table tabindex="0"><thead><tr><th>Prinzip</th><th>Beschreibung</th><th>Negativbeispiel</th></tr></thead><tbody><tr><td>Data-Ink-Ratio</td><td>Der Anteil der „Tinte&quot; zur Darstellung von Daten im Diagramm sollte möglichst hoch sein</td><td>Zu viele Gitterlinien, dekorative Elemente</td></tr><tr><td>Nicht-Daten-Elemente minimieren</td><td>Visuelle Elemente entfernen, die keine Informationen vermitteln</td><td>3D-Effekte, Schatten, Farbverlaufshintergründe</td></tr><tr><td>Konsistente Skalierung</td><td>Achsen bei null beginnen, gleichmäßige Teilung; bei abgeschnittenen Achsen muss dies klar gekennzeichnet werden</td><td>Y-Achse beginnt bei 95 ohne Hinweis</td></tr><tr><td>Sinnvoller Farbeinsatz</td><td>Farben zur Kodierung von Informationen verwenden, nicht zur Dekoration</td><td>Regenbogenfarben für geordnete Daten</td></tr><tr><td>Klare Beschriftungen</td><td>Titel, Achsenbeschriftungen, Legende und Einheiten dürfen nicht fehlen</td><td>Keine Einheiten, kein Zeitraum</td></tr></tbody></table><h3 id="_2-1-data-ink-ratio" tabindex="-1">2.1 Data-Ink-Ratio <a class="header-anchor" href="#_2-1-data-ink-ratio" aria-label="Permalink to “2.1 Data-Ink-Ratio”">​</a></h3><blockquote><p>Der Anteil der „Tinte&quot; zur Darstellung von Daten an der gesamten „Tinte&quot; im Diagramm sollte so hoch wie möglich sein.</p></blockquote><p>Einfach gesagt: <strong>Alles entfernen, was keine Informationen vermittelt</strong>.</p><table tabindex="0"><thead><tr><th>Sollte entfernt werden</th><th>Sollte beibehalten werden</th></tr></thead><tbody><tr><td>3D-Effekte, Schatten, Farbverläufe</td><td>Datenpunkte, Achsenbeschriftungen</td></tr><tr><td>Überflüssige Gitterlinien</td><td>Wichtige Referenzlinien (z. B. Zielwert)</td></tr><tr><td>Dekorative Icons</td><td>Legende (bei mehreren Datenreihen)</td></tr><tr><td>Auffällige Hintergrundfarben</td><td>Klare Titel und Einheiten</td></tr></tbody></table><h3 id="_2-2-konsistenzprinzip" tabindex="-1">2.2 Konsistenzprinzip <a class="header-anchor" href="#_2-2-konsistenzprinzip" aria-label="Permalink to “2.2 Konsistenzprinzip”">​</a></h3><ul><li><strong>Farbkonsistenz</strong>: Dieselbe Dimension in verschiedenen Diagrammen mit derselben Farbe darstellen, z. B. „Umsatz&quot; immer in Blau</li><li><strong>Skalakonsistenz</strong>: Achsen möglichst bei 0 beginnen lassen, es sei denn, es gibt triftige Gründe und eine klare Kennzeichnung</li><li><strong>Zeitkonsistenz</strong>: Die Abstände auf der Zeitachse sollten gleichmäßig sein; ungleichmäßige Zeitpunkte nicht als gleichmäßig darstellen</li></ul><h3 id="_2-3-lesbarkeitsprinzip" tabindex="-1">2.3 Lesbarkeitsprinzip <a class="header-anchor" href="#_2-3-lesbarkeitsprinzip" aria-label="Permalink to “2.3 Lesbarkeitsprinzip”">​</a></h3><ul><li><strong>Titel sollte eine Schlussfolgerung enthalten</strong>: Nicht „Monatlicher Umsatz&quot;, sondern „Umsatz seit 3 Monaten rückläufig&quot;</li><li><strong>Wichtige Punkte markieren</strong>: An Ausreißern und Wendepunkten Anmerkungen hinzufügen, um die Aufmerksamkeit des Lesers zu lenken</li><li><strong>Informationsdichte kontrollieren</strong>: Ein Diagramm sollte 1–2 Kernbotschaften vermitteln, nicht überladen</li></ul><div class="tip custom-block"><p class="custom-block-title">Drei Regeln für den Farbeinsatz</p><ol><li><strong>Dieselbe Kennzahl in derselben Farbe</strong>: Umsatz in allen Diagrammen in Blau darstellen, nicht einmal blau und einmal grün</li><li><strong>Geordnete Daten mit Farbverlauf</strong>: Temperatur von niedrig bis hoch mit Blau→Rot-Verlauf darstellen, keine diskreten Farben verwenden</li><li><strong>Farbenblindheitsfreundlich</strong>: Etwa 8 % der Männer haben eine Rot-Grün-Schwäche; vermeiden, wichtige Informationen nur durch Rot und Grün zu unterscheiden</li></ol></div><hr><h2 id="_3-dashboard-layout-verschiedene-szenarien-verschiedene-muster" tabindex="-1">3. Dashboard-Layout: Verschiedene Szenarien, verschiedene Muster <a class="header-anchor" href="#_3-dashboard-layout-verschiedene-szenarien-verschiedene-muster" aria-label="Permalink to “3. Dashboard-Layout: Verschiedene Szenarien, verschiedene Muster”">​</a></h2><p>Ein Dashboard ist eine organische Kombination mehrerer Diagramme. Ein gutes Dashboard stapelt nicht einfach Diagramme übereinander, sondern wählt basierend auf dem Verwendungszweck ein geeignetes Layoutmuster.</p>',19)),i(a),e[2]||(e[2]=t('<h3 id="vier-gangige-layoutmuster" tabindex="-1">Vier gängige Layoutmuster <a class="header-anchor" href="#vier-gangige-layoutmuster" aria-label="Permalink to “Vier gängige Layoutmuster”">​</a></h3><table tabindex="0"><thead><tr><th>Layoutmuster</th><th>Kernstruktur</th><th>Anwendungsbereich</th><th>Design-Hinweise</th></tr></thead><tbody><tr><td>Globaler Überblick</td><td>KPI-Karten + Trenddiagramm + Detailtabelle</td><td>Management-Tagesbericht, operatives Dashboard</td><td>Kernkennzahlen ganz oben platzieren, wichtigste Zahlen auf einen Blick</td></tr><tr><td>Vergleichsanalyse</td><td>Symmetrisches Links-Rechts-Layout</td><td>A/B-Tests, Jahresvergleich</td><td>Vergleichsdimensionen konsistent halten, Unterschiede hervorheben</td></tr><tr><td>Drilldown-Analyse</td><td>Von der Zusammenfassung zur Detailebene schrittweise</td><td>Vertriebsanalyse, Nutzerverhaltensanalyse</td><td>Klick-Interaktion unterstützen, schrittweise tiefer gehen</td></tr><tr><td>Echtzeit-Überwachung</td><td>Große Zahlen + Echtzeit-Kurven + Alarmstatus</td><td>Shopping-Festival-Dashboard, Serverüberwachung</td><td>Automatische Aktualisierung, dunkler Hintergrund, geeignet für Großbildschirme</td></tr></tbody></table><h3 id="_5-prinzipien-des-dashboard-designs" tabindex="-1">5 Prinzipien des Dashboard-Designs <a class="header-anchor" href="#_5-prinzipien-des-dashboard-designs" aria-label="Permalink to “5 Prinzipien des Dashboard-Designs”">​</a></h3><ol><li><strong>Zuerst fragen: „Wer schaut sich das an?&quot;</strong>: Der CEO sieht strategische Kennzahlen, das operative Team sieht Prozesskennzahlen, Ingenieure sehen technische Kennzahlen</li><li><strong>Die 5-Sekunden-Regel</strong>: Der Benutzer sollte die Kerninformation des Dashboards innerhalb von 5 Sekunden erfassen</li><li><strong>Informationsebenen</strong>: Das Wichtigste oben links, weniger Wichtiges darunter</li><li><strong>Scrollen reduzieren</strong>: Kerninhalte auf einen Bildschirm darstellen; vermeiden, dass Benutzer scrollen müssen, um wichtige Daten zu sehen</li><li><strong>Weißraum</strong>: Nicht jeden Zentimeter ausfüllen; angemessener Weißraum wirkt angenehmer</li></ol><div class="tip custom-block"><p class="custom-block-title">Dashboard vs. Bericht</p><ul><li><strong>Dashboard</strong>: Echtzeit/Near-Echtzeit, interaktiv, ausgerichtet auf Überwachung und schnelle Entscheidungsfindung</li><li><strong>Bericht</strong>: Regelmäßig erstellt (täglich/wöchentlich/monatlich), statisch, ausgerichtet auf detaillierte Analyse und Archivierung</li></ul><p>Die beiden stehen nicht in Konkurrenz zueinander, sondern ergänzen sich. Dashboards decken Probleme auf, Berichte analysieren sie vertieft.</p></div><hr><h2 id="_4-tool-auswahl-von-code-bibliotheken-bis-zu-bi-plattformen" tabindex="-1">4. Tool-Auswahl: Von Code-Bibliotheken bis zu BI-Plattformen <a class="header-anchor" href="#_4-tool-auswahl-von-code-bibliotheken-bis-zu-bi-plattformen" aria-label="Permalink to “4. Tool-Auswahl: Von Code-Bibliotheken bis zu BI-Plattformen”">​</a></h2><p>Visualisierungstools lassen sich in drei Ebenen unterteilen: Diagrammbibliotheken auf Code-Ebene, Diagrammbibliotheken für Datenanalyse und BI-Plattformen. Die Wahl hängt von der Komplexität der Anforderungen, den Interaktionsanforderungen und den technischen Fähigkeiten des Teams ab.</p><h3 id="_4-1-diagrammbibliotheken-auf-code-ebene" tabindex="-1">4.1 Diagrammbibliotheken auf Code-Ebene <a class="header-anchor" href="#_4-1-diagrammbibliotheken-auf-code-ebene" aria-label="Permalink to “4.1 Diagrammbibliotheken auf Code-Ebene”">​</a></h3><table tabindex="0"><thead><tr><th>Tool</th><th>Sprache/Plattform</th><th>Merkmale</th><th>Anwendungsbereich</th></tr></thead><tbody><tr><td>ECharts</td><td>JavaScript</td><td>sofort einsatzbereit, umfangreicher Diagrammtyp-Katalog, hervorragende chinesische Dokumentation</td><td>In Business-Systeme eingebettete Diagramme</td></tr><tr><td>D3.js</td><td>JavaScript</td><td>niedrigschwellig flexibel, jede Visualisierung anpassbar</td><td>Hochgradig angepasste Datenvisualisierung</td></tr><tr><td>Chart.js</td><td>JavaScript</td><td>leichtgewichtig und einfach, schneller Einstieg</td><td>Einfache Diagrammanforderungen</td></tr><tr><td>Matplotlib</td><td>Python</td><td>Standardbibliothek für wissenschaftliches Rechnen, statische Diagramme</td><td>Datenanalyse, Publikationsdiagramme</td></tr><tr><td>Plotly</td><td>Python/JS</td><td>interaktive Diagramme, 3D-Unterstützung</td><td>Datenexploration, Jupyter Notebook</td></tr></tbody></table><h3 id="_4-2-bi-plattformen-no-code-low-code" tabindex="-1">4.2 BI-Plattformen (No-Code/Low-Code) <a class="header-anchor" href="#_4-2-bi-plattformen-no-code-low-code" aria-label="Permalink to “4.2 BI-Plattformen (No-Code/Low-Code)”">​</a></h3><table tabindex="0"><thead><tr><th>Tool</th><th>Positionierung</th><th>Kernvorteil</th><th>Geeignetes Team</th></tr></thead><tbody><tr><td>Grafana</td><td>Überwachungsvisualisierung</td><td>Gute Unterstützung für Zeitreihendaten, Alarm-Integration</td><td>DevOps/SRE-Teams</td></tr><tr><td>Metabase</td><td>Leichtgewichtige BI</td><td>Open Source und kostenlos, Diagramme direkt aus SQL</td><td>Kleine und mittlere Teams für schnellen Aufbau</td></tr><tr><td>Apache Superset</td><td>Enterprise BI</td><td>Open Source, Unterstützung großer Datenquellen</td><td>Unternehmen mit einem Datenteam</td></tr><tr><td>Tableau</td><td>Kommerzielle BI</td><td>Drag-and-Drop-Bedienung, hervorragende Visualisierungsergebnisse</td><td>Business-Analysten</td></tr><tr><td>Power BI</td><td>Kommerzielle BI</td><td>Gute Integration in das Microsoft-Ökosystem</td><td>Unternehmen mit Microsoft-Technologie-Stack</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Auswahl-Empfehlungen</p><ul><li><strong>Entwickler, die Diagramme in Produkte einbetten</strong> → ECharts (gutes chinesisches Ökosystem) oder Chart.js (einfache Szenarien)</li><li><strong>Datenanalysten für explorative Analyse</strong> → Plotly + Jupyter oder Metabase</li><li><strong>DevOps-Überwachungs-Dashboard</strong> → Grafana (De-facto-Standard)</li><li><strong>Business-Teams für Self-Service-Analyse</strong> → Metabase (Open Source) oder Tableau (kommerziell)</li><li><strong>Hohe Anpassungsanforderungen</strong> → D3.js (steile Lernkurve, aber am meisten anpassbar)</li></ul></div><hr><h2 id="_5-haufige-fallen-diese-diagramme-tauschen-dich" tabindex="-1">5. Häufige Fallen: Diese Diagramme täuschen dich <a class="header-anchor" href="#_5-haufige-fallen-diese-diagramme-tauschen-dich" aria-label="Permalink to “5. Häufige Fallen: Diese Diagramme täuschen dich”">​</a></h2><p>Datenvisualisierung ist ein zweischneidiges Schwert: Gut eingesetzt deckt sie die Wahrheit auf, schlecht eingesetzt erzeugt sie Illusionen. Im Folgenden die häufigsten Visualisierungsfallen, die jeder Datenfachmann erkennen können sollte.</p><h3 id="_5-1-abgeschnittene-achsen" tabindex="-1">5.1 Abgeschnittene Achsen <a class="header-anchor" href="#_5-1-abgeschnittene-achsen" aria-label="Permalink to “5.1 Abgeschnittene Achsen”">​</a></h3><p>Den Startpunkt der Y-Achse von 0 auf eine größere Zahl zu ändern, lässt winzige Unterschiede wie gewaltige Veränderungen erscheinen.</p><table tabindex="0"><thead><tr><th>Szenario</th><th>Tatsächlicher Unterschied</th><th>Visueller Eindruck</th></tr></thead><tbody><tr><td>Y-Achse beginnt bei 0</td><td>Produkt A: 98 Punkte, Produkt B: 95 Punkte</td><td>Sehr geringer Unterschied</td></tr><tr><td>Y-Achse beginnt bei 90</td><td>Dieselben Daten</td><td>A wirkt um ein Vielfaches größer als B</td></tr></tbody></table><p><strong>Wann ist eine Abschneidung vertretbar?</strong> Wenn die absoluten Werte groß, die Veränderungen aber gering sind (z. B. Aktienkurs von 100 auf 105), ist eine Abschneidung gerechtfertigt, muss aber klar gekennzeichnet werden.</p><h3 id="_5-2-die-perspektivfalle-des-3d-kreisdiagramms" tabindex="-1">5.2 Die Perspektivfalle des 3D-Kreisdiagramms <a class="header-anchor" href="#_5-2-die-perspektivfalle-des-3d-kreisdiagramms" aria-label="Permalink to “5.2 Die Perspektivfalle des 3D-Kreisdiagramms”">​</a></h3><p>Die 3D-Perspektive lässt die Segmente, die näher am Betrachter liegen, größer erscheinen. Ein 25%-Segment kann in der 3D-Ansicht wie 35 % wirken.</p><p><strong>Lösung</strong>: Niemals 3D-Kreisdiagramme verwenden. Stattdessen ein normales Kreisdiagramm oder Donut-Diagramm verwenden — oder gleich ein Balkendiagramm.</p><h3 id="_5-3-farbfuhren" tabindex="-1">5.3 Farbführen <a class="header-anchor" href="#_5-3-farbfuhren" aria-label="Permalink to “5.3 Farbführen”">​</a></h3><table tabindex="0"><thead><tr><th>Falsche Vorgehensweise</th><th>Richtige Vorgehensweise</th></tr></thead><tbody><tr><td>Rot und Grün für Daten verwenden</td><td>Blau-Orange und andere farbenblinden-sichere Paletten verwenden</td></tr><tr><td>Für jede Kategorie eine andere Farbe verwenden</td><td>Innerhalb einer Reihe Abstufungen derselben Farbtonfamilie verwenden</td></tr><tr><td>Farben zur Kodierung kontinuierlicher Daten ohne Legende</td><td>Immer eine Farblegende und Wertbeschriftungen bereitstellen</td></tr><tr><td>Ungenügender Kontrast zwischen Hintergrund- und Datenfarbe</td><td>WCAG-AA-Kontraststufe sicherstellen</td></tr></tbody></table><h3 id="_5-4-weitere-haufige-fehler" tabindex="-1">5.4 Weitere häufige Fehler <a class="header-anchor" href="#_5-4-weitere-haufige-fehler" aria-label="Permalink to “5.4 Weitere häufige Fehler”">​</a></h3><table tabindex="0"><thead><tr><th>Falle</th><th>Problem</th><th>Behebung</th></tr></thead><tbody><tr><td>Doppelte Y-Achse</td><td>Zwei unabhängige Kennzahlen teilen sich die X-Achse und suggerieren eine kausale Beziehung</td><td>In zwei separate Diagramme aufteilen oder explizit auf fehlende Kausalität hinweisen</td></tr><tr><td>Flächenillusion</td><td>Den Radius statt der Fläche eines Kreises zur Darstellung von Werten verwenden</td><td>Bei Verdopplung des Werts die Fläche verdoppeln, nicht den Radius</td></tr><tr><td>Ungleichmäßige Zeitachse</td><td>Die Abstände für Januar, März und Dezember sind gleich</td><td>Nach dem tatsächlichen zeitlichen Verhältnis anordnen</td></tr><tr><td>Zu viele Kategorien</td><td>Ein Kreisdiagramm mit 15 Segmenten</td><td>Bei mehr als 5 Kategorien ein Balkendiagramm verwenden oder „Sonstige&quot; zusammenfassen</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Ethische Grundsätze der Visualisierung</p><p>Der Zweck der Visualisierung ist es, das <strong>Verständnis zu fördern</strong>, nicht die <strong>Wahrnehmung zu manipulieren</strong>. Stelle dir bei jedem Diagramm die Fragen:</p><ul><li>Würde mich dieses Diagramm als Leser zu falschen Schlussfolgerungen verleiten?</li><li>Habe ich ungünstige Daten verschwiegen?</li><li>Stellen Achsen, Maßstab und Farben die Daten gerecht dar?</li></ul></div><hr><h2 id="zusammenfassung" tabindex="-1">Zusammenfassung <a class="header-anchor" href="#zusammenfassung" aria-label="Permalink to “Zusammenfassung”">​</a></h2><p>Datenvisualisierung ist die „letzte Meile&quot; der Wertübertragung von Daten. Selbst die beste Analyse ist wertlos, wenn sie nicht richtig verstanden wird.</p><p>Rückblick auf die Kernpunkte dieses Kapitels:</p><ol><li><strong>Das richtige Diagramm wählen</strong>: Den Diagrammtyp basierend auf dem Datenzweck (Vergleich, Trend, Anteil, Verteilung, Beziehung) auswählen</li><li><strong>Designprinzipien</strong>: Hohe Data-Ink-Ratio, Konsistenz und Lesbarkeit sind die drei Kernprinzipien</li><li><strong>Dashboard-Layout</strong>: Die vier Muster — Übersichtstyp, Vergleichstyp, Drilldown-Typ und Echtzeit-Typ — decken die meisten Szenarien ab</li><li><strong>Tool-Auswahl</strong>: Von ECharts bis Grafana, je nach Teamfähigkeit und Anforderungskomplexität wählen</li><li><strong>Fallen vermeiden</strong>: Abgeschnittene Achsen, 3D-Kreisdiagramme und Farbführen sind die häufigsten Mittel zur Irreführung</li></ol><h2 id="weiterfuhrende-literatur" tabindex="-1">Weiterführende Literatur <a class="header-anchor" href="#weiterfuhrende-literatur" aria-label="Permalink to “Weiterführende Literatur”">​</a></h2><ul><li><a href="https://www.edwardtufte.com/tufte/books_vdqi" target="_blank" rel="noreferrer">The Visual Display of Quantitative Information</a> - Edward Tuftes Visualisierungsklassiker</li><li><a href="https://echarts.apache.org/zh/index.html" target="_blank" rel="noreferrer">ECharts Offizielle Dokumentation</a> - Die beliebteste chinesische Diagrammbibliothek</li><li><a href="https://d3js.org/" target="_blank" rel="noreferrer">D3.js</a> - Leistungsstarke Low-Level-Visualisierungsbibliothek</li><li><a href="https://grafana.com/" target="_blank" rel="noreferrer">Grafana</a> - De-facto-Standard für Überwachungsvisualisierung</li><li><a href="https://www.data-to-viz.com/" target="_blank" rel="noreferrer">From Data to Viz</a> - Entscheidungsbaum zur Diagrammtypauswahl</li><li><a href="https://colorbrewer2.org/" target="_blank" rel="noreferrer">ColorBrewer</a> - Tool für farbenblinden-sichere Farbschemata</li></ul>',35))])}const k=s(h,[["render",o]]);export{p as __pageData,k as default};
